<?php include "../includes/cek_session.php"; include "../config/koneksi.php"; hanya_role('Administrator'); $title="Tambah Barang"; include "../includes/header.php";
if($_SERVER['REQUEST_METHOD']==='POST'){ $kode=trim($_POST['kode_barang']);$nama=trim($_POST['nama_barang']);$harga=(float)$_POST['harga'];$stok=(int)$_POST['stok'];$satuan=trim($_POST['satuan']);$status=$_POST['status'];
$stmt=mysqli_prepare($koneksi,"INSERT INTO tb_barang(kode_barang,nama_barang,harga,stok,satuan,status) VALUES(?,?,?,?,?,?)");mysqli_stmt_bind_param($stmt,"ssdiss",$kode,$nama,$harga,$stok,$satuan,$status);
if(mysqli_stmt_execute($stmt)){header("Location: index.php");exit;} $error=mysqli_stmt_error($stmt);}
?>
<div class="page-head"><h1>Tambah Barang</h1></div><div class="panel"><?php if(isset($error)):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?>
<form method="post"><div class="form-grid"><div class="form-group"><label>Kode Barang</label><input class="form-control" name="kode_barang" required></div><div class="form-group"><label>Nama Barang</label><input class="form-control" name="nama_barang" required></div><div class="form-group"><label>Harga</label><input class="form-control" type="number" name="harga" min="0" required></div><div class="form-group"><label>Stok</label><input class="form-control" type="number" name="stok" min="0" required></div><div class="form-group"><label>Satuan</label><input class="form-control" name="satuan" placeholder="pcs" required></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option>Aktif</option><option>Nonaktif</option></select></div></div><br><button class="btn">Simpan</button> <a class="btn light" href="index.php">Batal</a></form></div><?php include "../includes/footer.php"; ?>